export const sourcePages = {
  "125": "<h2>125</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">第2章</strong></span></h1>\n<h1><span data-source-color=\"white\" data-source-background=\"pink\" style=\"color:#ffffff;background-color:#f0a0a0\"><strong class=\"source-bold\">列強の侵略とアジアの変革</strong></span></h1>",
  "126": "<h2>126</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">近代の西アジア</strong></span></h1>\n<p>いよいよアジアの近現代史に入るよ。最初は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">西アジア</strong></u>からだ。今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">オスマン帝国（トルコ）</strong></u>と<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ガージャール朝ペルシア</strong></u>の2国について見ていくよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国(トルコ)</strong></span></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">オスマン帝国の衰退</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">127〜129ページ</span></td></tr><tr><td></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">オスマン帝国の近代化</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">129〜135ページ</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガージャール朝ペルシア(イラン)</strong></span></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">ガージャール朝の衰退と混乱</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">135〜139ページ</span></td></tr></tbody></table></div>\n<blockquote><p>オスマン帝国の近代化は、東方問題とつなげて勉強してね。今回はオスマン帝国目線で見るよ！</p></blockquote>\n<p>少なくとも17世紀までは、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヨーロッパ各国はオスマン帝国にはかなわなかった</strong></u>。だって産業革命が始まる前には、ヨーロッパはユーラシア大陸の単なる辺境だったからね。でも<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">18世紀ごろからだんだんとオスマン帝国が衰退</strong></u>し始め、ヨーロッパで<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">産業革命が始まるとヨーロッパがオスマン帝国を逆転</strong></u>して、気づけばオスマン帝国は<ruby>列強<rt>れっきょう</rt></ruby>の進出を受け始めるよ。同じころ、ペルシア（イラン）の<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ガージャール朝にもイギリスやロシアが進出し始める</strong></u>。今回は、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span>の「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">東方問題</strong></u>」で出てきた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イギリスとロシアを中心とする列強の対立</strong></u>と非常に関係が深い範囲だよ。ヨーロッパ目線で見た「東方問題」も、オスマン帝国目線で見てみるとまた別の側面が見えてくるはずだ。</p>\n<p>それじゃあ、近代の西アジアの始まり〜。</p>",
  "127": "<h2>127</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">オスマン帝国の衰退</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">オスマン帝国の衰退</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">圧倒的に強かったはずのオスマン帝国が、領土を失い始めた！</strong></span></h4>\n<p>もし、17世紀末の時点で世界の国々を強い順に並べると、たぶん<strong class=\"source-bold\">1位は中国の<ruby>清<rt>シン</rt></ruby>朝</strong>、<strong class=\"source-bold\">2位はオスマン帝国（トルコ）</strong>、<strong class=\"source-bold\">3位はインドのムガル帝国</strong>だろうね。大航海時代以降、ヨーロッパ各国は世界各地に進出して、アメリカ大陸では植民地を拡大したから「なんかヨーロッパすごい」って思うかもしれないけど、よく考えてごらん。<strong class=\"source-bold\">ヨーロッパ諸国がアジアで征服した国って何があるかな？</strong> まあ、東南アジアの<strong class=\"source-bold\">マラッカ王国</strong>とか、あるいは<strong class=\"source-bold\">フィリピン</strong>とか、征服したところはゼロではないけど、<strong class=\"source-bold\">アジア各地の大帝国は1つも滅んでいない</strong>よね。なぜって？ だって<strong class=\"source-bold\">ヨーロッパのほうが弱い</strong>んだもん。これから話す<strong class=\"source-bold\">オスマン帝国はヨーロッパが恐れた大国の1つ</strong>だ。</p>\n<p>例えば、16世紀の<strong class=\"source-bold\">スレイマン1世がやった第1次ウィーン包囲</strong>は、もし冬が寒くなかったら、たぶんオスマン帝国がウィーンを征服してるし、<strong class=\"source-bold\">プレヴェザ海戦</strong>では、スペインがボッコボコにされてる。こんなふうに<strong class=\"source-bold\">オスマン帝国が圧倒的に優位だった</strong>ところから、ヨーロッパが巻き返し始めたのは17世紀末になってからだ。</p>\n<p>1683年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次ウィーン包囲</strong></span><strong class=\"source-bold\">に失敗した</strong>オスマン帝国は、オーストリアやポーランドなどの反撃を受け、1699年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルロヴィッツ条約</strong></span>を結んで<strong class=\"source-bold\">オーストリアに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-bold\">ハンガリー</strong></span></strong>やトランシルヴァニアなどを<ruby>割譲<rt>かつじょう</rt></ruby>した。これって、<strong class=\"source-bold\">オスマン帝国が初めて敗戦国として領土を失った</strong>条約だよ。ここから少しずつ衰退するんだけど、だからといって一気に崩壊はしない。だって、オスマン帝国の領土は、もともとすごく広いからさ。</p>\n<blockquote><p>ハンガリーを取ると、オーストリアは支配地が倍増！ オスマン帝国のダメージはそこまではないね</p></blockquote>\n<p>ただ、18世紀に入ると<strong class=\"source-bold\">ロシアの南下政策</strong>が進み、<strong class=\"source-bold\">エカチェリーナ2世</strong>との<strong class=\"source-bold\">ロシア＝トルコ戦争 [1768〜74]で大敗した</strong>オスマン帝国は、<strong class=\"source-bold\">キュチュク＝カイナルジ条約</strong>で<strong class=\"source-bold\">クリミア＝ハン国【クリム＝ハン国】</strong>の<ruby>宗主<rt>そうしゅ</rt></ruby>権を放棄させられ、<strong class=\"source-bold\">黒海の自由航行権</strong>と<strong class=\"source-bold\">ギリシア正教徒の保護権</strong>をロシアに与えた。こうしてオスマン帝国の弱体化が明らかになると、ロシアだけじゃなくて<strong class=\"source-bold\">ヨーロッパ各国の進出が激化</strong>したんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">近代化を始めたけど、保守派の反発とエジプトの自立に苦しめられた！</strong></span></h4>\n<p>さすがに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国</strong></span>も「<strong class=\"source-bold\">近代化をしなきゃマズい</strong>」って思い始めたよ。だって、軍隊がどんどん弱くなってる……。しかも国内ではトルコ人<ruby>騎士<rt>きし</rt></ruby>が没落して<strong class=\"source-bold\">ティマール制が崩壊</strong>し、軍が弱くなるだけじゃなくて<strong class=\"source-bold\">徴税もできなくなってきた</strong>んだもん（ティマールって、<strong class=\"source-bold\">騎士に徴税権を与える制度</strong>だったよね）。しかも、かわりにつくった<strong class=\"source-bold\">徴税<ruby>請負<rt>うけおい</rt></ruby>制</strong>で地方有力者（アーヤーン）が自立して中央政府の力が弱く</p>",
  "128": "<h2>128</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> 近代の西アジア</p>\n<p>なり、しかも<strong class=\"source-bold\">イェニチェリ軍団も特権階級となって</strong>スルタンの政治を邪魔し始める。こんなんじゃ、どんどん弱くなる一方だよ。</p>\n<p>1789年、フランス革命の<ruby>勃発<rt>ぼっぱつ</rt></ruby>と同じ年に即位した<strong class=\"source-bold\">セリム3世</strong>はヨーロッパ式の<strong class=\"source-bold\">新軍【ニザーム＝ジェディット】</strong>をつくって軍隊を強くしなきゃ！って思ったんだけど、特権を失う<strong class=\"source-bold\">イェニチェリの反発で殺されてしまった</strong>。というか、<ruby>奴隷<rt>どれい</rt></ruby>身分のイェニチェリに殺されてる時点で、制度がおかしくなってる……。</p>\n<p>でも、この時代に一番<strong class=\"source-bold\">オスマン帝国を弱らせたのはエジプトの自立</strong>だよ。<strong class=\"source-bold\">ナポレオンのエジプト遠征</strong>を受けたオスマン帝国は、<strong class=\"source-bold\">アルバニア<ruby>傭兵<rt>ようへい</rt></ruby>隊</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムハンマド＝アリー</strong></span>を派遣した。でも、これがオスマン帝国の運命を狂わせたんだよ。ナポレオン軍を破った<strong class=\"source-bold\">イギリス軍がアミアンの和約によって撤退</strong>したあと、エジプトはマムルーク軍の派閥抗争で大混乱になった。この<strong class=\"source-bold\">混乱をムハンマド＝アリーが収めた</strong>から、カイロ市民が「エジプトを支配するのはあなたしかいない！」と大熱狂。こうして<strong class=\"source-bold\">ムハンマド＝アリーはエジプト<ruby>総督<rt>そうとく</rt></ruby>となり</strong>、オスマン帝国も認めるしかなくなった。ここから、エジプトは<strong class=\"source-bold\">ムハンマド＝アリー朝</strong>だよ。</p>\n<h3><strong class=\"source-bold\">〈オスマン帝国の衰退〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">キュチュク＝カイナルジ条約(1774)でオスマン帝国が宗主権を放棄</span></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">カルロヴィッツ条約(1699)で墺に割譲</span></td><td></td></tr><tr><td><strong class=\"source-bold\">ロシア帝国</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">ハンガリー</strong></td><td>[1699(墺)]</td></tr><tr><td><strong class=\"source-bold\">トランシルヴァニア</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">クリミア＝ハン国</strong></td><td>[1783(露)]</td></tr><tr><td>イスタンブル</td><td></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\">黒海</em></td><td></td></tr><tr><td><strong class=\"source-bold\">ギリシア</strong></td><td>[1830独立]</td></tr><tr><td><strong class=\"source-bold\">オスマン帝国(トルコ)</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">シリア</strong></td><td></td></tr><tr><td>イェルサレム</td><td></td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td><strong class=\"source-bold\">(ムハンマド＝アリー朝)</strong></td></tr><tr><td><strong class=\"source-bold\">ワッハーブ王国</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">スーダン</strong></td><td></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"area\" style=\"color:#e52715\">■</span></td><td>オスマン帝国最大領域</td></tr><tr><td><span data-source-color=\"black\" data-source-marker=\"arrow\" style=\"color:#001000\">→</span></td><td>ロシアの南下政策</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"arrow\" style=\"color:#e52715\">→</span></td><td>ムハンマド＝アリーの勢力拡大</td></tr></tbody></table></div>\n<blockquote><p>エジプトの自立、ギリシアの独立……オスマン帝国の衰退が一気に進んじゃった！</p></blockquote>",
  "129": "<h2>129</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">オスマン帝国の近代化</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>これ以後、<strong class=\"source-bold\">ムハンマド＝アリーは勝手にエジプトの近代化を進め</strong>、マムルーク軍人を計略で殺してしまうと、徴兵制を導入して<strong class=\"source-bold\">西欧式の軍団を編成</strong>した。さらに徴税請負をやめて人びとに直接課税し、<strong class=\"source-bold\">財政も強化</strong>したんだ。こんなふうに強くなると、もはやスルタンの言うことを聞かなくなる。しかも、ムハンマド＝アリーは<strong class=\"source-bold\">スーダンの征服</strong>で支配地を拡大しちゃった。もはや、ムハンマド＝アリーは独立したつもりなんだろうね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">近代化を進めるエジプト。オスマン帝国との戦争の結末はどうなった？</strong></span></h4>\n<p>ここからは<strong class=\"source-bold\">東方問題</strong>（<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第5回</strong></span> <span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➜P.95</strong></span>）のところともあわせて見てみてね。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア独立戦争</strong></span>だけではなく、アラビア半島の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワッハーブ運動</strong></span>の<ruby>鎮圧<rt>ちんあつ</rt></ruby>に苦しんでいた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコ</strong></span>）は、軍の近代化に成功している<strong class=\"source-bold\">ムハンマド＝アリーに支援を要請</strong>し、かわりに<strong class=\"source-bold\">シリア<ruby>割譲<rt>かつじょう</rt></ruby>を約束</strong>したよね。ムハンマド＝アリーは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワッハーブ王国</strong></span>を征服したけど、ギリシア独立戦争では勝てなかったんだ。その後、シリアの領有をめぐってオスマン帝国と対立、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次エジプト＝トルコ戦争</strong></span>が起きたんだ。この戦争は<strong class=\"source-bold\">英仏の圧力</strong>によってキュタヒヤ条約が結ばれて、<strong class=\"source-bold\">ムハンマド＝アリーがシリア領有権を獲得</strong>したよね。</p>\n<p>その後、調子に乗った<strong class=\"source-bold\">ムハンマド＝アリーがエジプト、シリアの<ruby>世襲<rt>せしゅう</rt></ruby>権を要求</strong>（要はオスマン帝国からの独立だよ）すると、再び戦争となった。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次エジプト＝トルコ戦争</strong></span>だ。この戦争では、イギリスの戦略から<strong class=\"source-bold\">イギリス・オーストリア・プロイセン・ロシアの4国がオスマン帝国を支援</strong>したから、ムハンマド＝アリーもさすがに勝てない。結局、<strong class=\"source-bold\">ムハンマド＝アリーがシリアの領有権を<ruby>放棄<rt>ほうき</rt></ruby></strong>して、<strong class=\"source-bold\">エジプト、スーダンの世襲権のみが承認</strong>されたよね。この敗北でエジプトの近代化も結局挫折させられて、イギリスに<ruby>市場<rt>しじょう</rt></ruby>を開放するしかなくなったんだよ。</p>\n<p>こうして、2回のエジプト＝トルコ戦争によって、オスマン帝国、エジプトのどちらもヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>の進出に悩まされることになったんだよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">オスマン帝国の近代化</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">エジプト＝トルコ戦争で負けそうになって、仕方なくタンジマートを開始！</strong></span></h4>\n<p><strong class=\"source-bold\">ギリシア独立戦争ではイェニチェリ軍団がほとんど役に立たず</strong>、ムハンマド＝アリーの西洋式の軍団が活躍したのを見て、スルタンの<strong class=\"source-bold\">マフムト2世</strong>は軍の近代化を決意、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イェニチェリ軍団を解散</strong></span>するために、軍団本部に集中砲火を浴びせて<ruby>潰<rt>つぶ</rt></ruby>し、完全に<strong class=\"source-bold\">西洋式の常備軍（ムハンマド常勝軍）に切り替え</strong>た。これが<strong class=\"source-bold\">オスマン帝国（トルコ）の近代化の第1歩</strong>だよ。そして、軍の再編で財政難となったから、地方有力者（アーヤーン）の勢力を抑え込んで<strong class=\"source-bold\">中央集権化を進めた</strong>よ。</p>\n<p>しかし、オスマン帝国には次のピンチが訪れた。それが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト＝トルコ戦争</strong></span>だ。イギリスの支援を受けるために<strong class=\"source-bold\">トルコ＝イギリス通商条約</strong>（1838）を結んで従来のカピチュレーションを固定化し、<strong class=\"source-bold\">自由貿易を認めた</strong>んだけど、イギリス製品の流入</p>",
  "130": "<h2>130</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> 近代の西アジア</p>\n<p>で<strong class=\"source-bold\">オスマン帝国の国内産業が衰退</strong>したんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">オスマン帝国（トルコ）の近代化</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">マフムト2世</strong> [位1808〜39]</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イェニチェリ軍団の解散</strong></span> [1826] <span data-source-color=\"green\" style=\"color:#315837\">→</span> <strong class=\"source-bold\">西洋式の常備軍を整備</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">トルコ＝イギリス通商条約</strong>[1838]<span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">オスマン帝国の国内産業が衰退</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">アブデュルメジト1世</strong> [位1839〜61]</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">ギュルハネ<ruby>勅令<rt>ちょくれい</rt></ruby></strong> [1839] ……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンジマート</strong></span>の開始</p>\n<p>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア戦争</strong></span>以降、<strong class=\"source-bold\">外債で財政<ruby>破綻<rt>はたん</rt></ruby></strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アブデュルハミト2世</strong></span> [位1876〜1909]</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国憲法</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミドハト憲法</strong></span>】 [1876] ……<ruby>大宰相<rt>だいさいしょう</rt></ruby><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミドハト＝パシャ</strong></span>が<ruby>起草<rt>きそう</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露土<rt>ろと</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア＝トルコ戦争</strong></span>】の<ruby>勃発<rt>ぼっぱつ</rt></ruby>で<strong class=\"source-bold\">憲法を停止、議会も閉鎖</strong></p>\n<p>※露土戦争に敗北し、<strong class=\"source-bold\">バルカン半島の領土を大幅に失う</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> 「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">統一と進歩委員会</strong></span>」結成 [1889] ……<strong class=\"source-bold\">立憲政の復活を目指す</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>メンバーは「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年トルコ人</strong></span>」と称された</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span>ギリシアの<strong class=\"source-bold\">サロニカ</strong>を拠点に、<strong class=\"source-bold\">軍の青年将校と合流</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年トルコ革命</strong></span> [1908] ……<strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争における日本の勝利が影響</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><strong class=\"source-bold\">憲法、議会の復活</strong><span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">立憲君主政</strong>の復活（<strong class=\"source-bold\">第二次立憲政</strong>）</p></blockquote>\n<p>戦争中にマフムト2世が急死すると、新スルタンに即位した<strong class=\"source-bold\">アブデュルメジト1世</strong>は英仏の支援を得るために、さらに改革を進めることを発表した（<strong class=\"source-bold\">ギュルハネ勅令</strong>）。ここから始まる改革が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンジマート</strong></span>だよ。ギュルハネ勅令では、<strong class=\"source-bold\">徴税請負制の廃止</strong>と公平な課税、公平な裁判の実施、<strong class=\"source-bold\">ムスリムと非ムスリムの平等</strong>、収賄（わいろ）の禁止など、<strong class=\"source-bold\">行政・財政・立法・司法・軍事にわたる幅広い分野での改革を目指す</strong>ことが示されたんだけど、そうはうまくいかない。なぜなら、<strong class=\"source-bold\">国内の保守派の抵抗</strong>がむちゃくちゃ強いからだよ。特に、徴税の利権を取られる地方有力者（アーヤーン）の反発で、<strong class=\"source-bold\">徴税請負制が復活</strong>して改革は逆戻り。しかも、「改革が進まないじゃないか！」って怒ったバルカン半島の諸民族が反乱を起こすし、さらに対外的な危機にも襲われた。それが<strong class=\"source-bold\">クリミア戦争</strong>だ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">クリミア戦争が勃発！……借金が増えすぎて財政が破綻！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クリミア戦争</strong></span>をオスマン帝国目線で見てみよう。結果だけを見て「<strong class=\"source-bold\">英仏の支援で勝った</strong>からいいでしょ」って思っちゃいけない！ 支援してもらった代償は大きいよ〜。まず、<strong class=\"source-bold\">ムスリムと非ムスリムの社会的平等</strong>と権利の保障が確認された。</p>",
  "131": "<h2>131</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">オスマン帝国の近代化</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>宗教や民族の区別なく、法のもとでオスマン帝国の臣民の平等を認めるから、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン主義</strong></span>」って言われるよ。これは<strong class=\"source-bold\">イギリスやフランスなど<ruby>列強<rt>れっきょう</rt></ruby>が要求したこと</strong>なんだけど、国内的にはバルカン半島での非ムスリム共同体（<strong class=\"source-bold\">ミッレト</strong>）の対立を抑えることにもなったよ。</p>\n<p>もっと大きな影響が、「<strong class=\"source-bold\">外債による財政破綻</strong>」だ。クリミア戦争の戦費が足りなかったオスマン帝国は、<strong class=\"source-bold\">イギリスに<ruby>借款<rt>しゃっかん</rt></ruby>（外国からの借金）をした</strong>んだけど、戦後も<strong class=\"source-bold\">借款を重ねて</strong>返済できなくなり（「外債の利子不払いを宣言」っていう場合もあるよ）、<strong class=\"source-bold\">オスマン帝国の国家財政は破綻</strong>した。</p>\n<p>こうした状況を見て、タンジマートの時期に<strong class=\"source-bold\">ヨーロッパ的な近代教育を受けた知識人</strong>たちは「近代化を進めないと、列強の植民地になってしまう！」という危機感を持ったんだ。彼らは近代化のためには「<strong class=\"source-bold\">オスマン帝国をスルタンの<ruby>専制<rt>せんせい</rt></ruby>政治から立憲君主政に変えなきゃいけない</strong>」って主張し、自ら「新オスマン人」と名乗って、スルタン（アブデュルアジーズ）の退位を要求するデモを始めた。スルタンは<ruby>弾圧<rt>だんあつ</rt></ruby>しようとしたけどデモは全く収まらず、やむなくスルタンは退位したよ。そして、その政情不安のなかで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アブデュルハミト2世</strong></span>が<strong class=\"source-bold\">立憲君主政を支持してスルタンに即位</strong>したんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">名前が似ているから気をつけよう！</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">アブデュルメジト1世</strong> [位1839〜61]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンジマート</strong></span>の開始……<strong class=\"source-bold\">ギュルハネ勅令</strong>による</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アブデュルハミト2世</strong></span> [位1876〜1909]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国憲法</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミドハト憲法</strong></span>】の制定 [1876]</p>\n<p>……<strong class=\"source-bold\">タンジマートの集大成</strong>。大宰相<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミドハト＝パシャ</strong></span>による</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露土戦争</strong></span>の勃発を口実に<strong class=\"source-bold\">憲法停止＝専制政治を復活</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年トルコ革命</strong></span><strong class=\"source-bold\">により退位</strong> [1909]</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">知識人の要求でついにオスマン帝国憲法制定！ でも専制政治に逆戻り</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アブデュルハミト2世</strong></span>は、即位前の約束通り「新オスマン人」を指導していた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミドハト＝パシャ</strong></span>を<strong class=\"source-bold\">大宰相に任命</strong>した。そしてミドハト＝パシャによって起草された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスマン帝国憲法</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミドハト憲法</strong></span>】が発布されたよ。これは<strong class=\"source-bold\">オスマン帝国最初の憲法</strong>であると同時に、<strong class=\"source-bold\">アジア初の憲法</strong>だ。内容は<strong class=\"source-bold\">タンジマートの集大成</strong>って考えればいいよ。この憲法に基づいて、スルタンの任命による上院と、帝国の各州から選出される下院からなる<strong class=\"source-bold\">二院制議会</strong>が設置されたんだけど……いざ議会を開いてみると、議員たちは<strong class=\"source-bold\">大臣たちの<ruby>汚職<rt>おしょく</rt></ruby>や官僚の不正、さらにはスルタンと特権商人の<ruby>癒着<rt>ゆちゃく</rt></ruby>などをさんざん批判し始めた</strong>んだ。これまでの政治を考えたらそうなるよ……。</p>",
  "132": "<h2>132</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> 近代の西アジア</p>\n<p>こうなるとアブデュルハミト2世も我慢できなくなってくる。<strong class=\"source-bold\">ミドハト＝パシャを<ruby>流刑<rt>るけい</rt></ruby></strong>にしちゃった。しかも対外的には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露土<rt>ろと</rt></ruby>戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア＝トルコ戦争</strong></span>】が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！ トルコは大敗していたから、アブデュル＝ハミト2世は<strong class=\"source-bold\">露土戦争の勃発を口実に憲法を停止</strong>して議会も閉鎖し、以後30年間も<ruby>専制<rt>せんせい</rt></ruby>政治を続けた。</p>\n<p>しかも露土戦争の結果はオスマン帝国にとっては辛いものだよ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サン＝ステファノ条約</strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンテネグロ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルーマニア</strong></span>の独立を認めることになり、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>を<strong class=\"source-bold\">事実上ロシアに奪われた</strong>。その後の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会議</strong></span>で、一応<strong class=\"source-bold\">ブルガリアだけはオスマン帝国<ruby>宗主<rt>そうしゅ</rt></ruby>下の自治国</strong>ってことにはなったけど、<strong class=\"source-bold\">バルカン半島でかなりの領土を失った</strong>ことは間違いない（東方問題のところの地図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➜P.107</strong></span>を見てみてね）。<ruby>列強<rt>れっきょう</rt></ruby>の対立のウラで、オスマン帝国はどんどん弱くなっていったんだよ。</p>\n<p>このあと、アブデュルハミト2世はヨーロッパ列強に対抗するために、<strong class=\"source-bold\">アフガーニー</strong>をイスタンブルに招き、彼の提唱した<strong class=\"source-bold\">パン＝イスラーム主義</strong>を利用して帝国を維持しようとしたんだ。パン＝イスラーム主義というのは、ヨーロッパ（キリスト教）の帝国主義に対抗するために<strong class=\"source-bold\">イスラーム教徒が連携</strong>して、<strong class=\"source-bold\">イスラーム教徒が自らの手で「非西洋的な改革</strong>（ヨーロッパに頼らずにイスラーム文明を復活させる）<strong class=\"source-bold\">」を進める</strong>という考え方だよ。アブデュルハミト2世はパン＝イスラーム主義のオイシイところだけもらって、「<strong class=\"source-bold\">カリフであるオスマン帝国の下にイスラーム教徒を統合して、ヨーロッパに対抗する</strong>」っていうふうに変えたんだけど、<strong class=\"source-bold\">世界のイスラーム教徒にはかなり支持された</strong>んだ。そうはいっても、アフガーニーの考え方とは違う。<strong class=\"source-bold\">アフガーニーは<ruby>幽閉<rt>ゆうへい</rt></ruby>されて、イスタンブルで病死</strong>してしまったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">西欧式の教育を受けた知識人が「統一と進歩委員会」を結成！</strong></span></h4>\n<p>19世紀後半になっても、<strong class=\"source-bold\">オスマン帝国ではスルタンの専制政治が続いていた</strong>けど、セリム3世の時から進んだ改革によって西洋文化が流入して、<strong class=\"source-bold\">ヨーロッパ的な教育を受けた人も増えていた</strong>。彼らは「どうしたら<ruby>列強<rt>れっきょう</rt></ruby>の侵略からオスマン帝国を救えるのか？」ってことを真剣に考えたんだけど、どう見ても<strong class=\"source-bold\">オスマン帝国が停滞している原因はスルタンの専制政治だ</strong>。そこで<strong class=\"source-bold\">ミドハト憲法の復活と専制政治の打倒</strong>を目指して「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">統一と進歩委員会</strong></span>」を結成した。ここに参加したメンバーは「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年トルコ人</strong></span>」と呼ばれているよ。</p>\n<p>アブデュル＝ハミト2世の<ruby>弾圧<rt>だんあつ</rt></ruby>を受けた<strong class=\"source-bold\">「統一と進歩委員会」のメンバーはパリに<ruby>亡命<rt>ぼうめい</rt></ruby>して活動を続け</strong>、ロシアから亡命してきたトルコ人やクルド人、アルメニア人などを吸収しながら、少しずつ運動を拡大していったんだ。</p>\n<blockquote><p>ついに、専制政治に反対する人たちが集まり始めたよ。「青年トルコ人」は彼らの総称だ！</p></blockquote>",
  "133": "<h2>133</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">オスマン帝国の近代化</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><strong class=\"source-bold\">＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-bold\">α</strong></span>ちょっと寄り道</strong></h3>\n<blockquote><p>トルコはとても親日的な国なんだけど、背景を知ってるかな？</p>\n<p>アブデュルハミト2世は、表向きは日本との友好を深めるため、ウラにはアジア各地に「オスマン帝国（トルコ）を中心とするパン＝イスラーム主義を宣伝」することを目的に、木造軍艦のエルトゥールル号を日本へ派遣した。当時、どちらも列強の不平等条約に苦しめられていたからね。</p>\n<p>1890年、エルトゥールル号がオスマン帝国へ帰る際、<ruby>紀伊<rt>きい</rt></ruby>半島の先端、紀伊大島の沖で台風にあおられて<ruby>座礁<rt>ざしょう</rt></ruby>し、沈没しちゃった。乗組員620名のうち500名以上が犠牲となるなか、大島の住民の決死の救助によって69名が救出されたんだ。この事件が日本全国に伝わると日本中から<ruby>義捐金<rt>ぎえんきん</rt></ruby>が集まり、明治政府も軍艦<ruby>比叡<rt>ひえい</rt></ruby>と<ruby>金剛<rt>こんごう</rt></ruby>で生存者をオスマン帝国に送り届けることを決めた。以後、日本からオスマン帝国へと学者や技術者が派遣されて、オスマン帝国の近代化に協力したんだよ。そして、トルコ革命を成功させたムスタファ＝ケマルは、トルコの近代化を助けてくれた日本への感謝を忘れないためにも、この軍艦遭難事件を教科書に載せて学校で教えることにした。みんなにも、親日的な国トルコとの友好の原点を知っていてほしいんだ。</p></blockquote>\n<h3><strong class=\"source-bold\">〈第一次世界大戦直前のオスマン帝国〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><strong class=\"source-bold\">オーストリア＝ハンガリー帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ロシア帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ボスニア・ヘルツェゴヴィナ</strong>（墺）</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ルーマニア</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">セルビア</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ブルガリア</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">モンテネグロ</strong></span></td></tr><tr><td>イスタンブル</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ギリシア</strong></span></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国(トルコ)</strong></td></tr><tr><td><strong class=\"source-bold\">チュニジア</strong>（仏）</td></tr><tr><td><strong class=\"source-bold\">リビア</strong>（伊）</td></tr><tr><td><strong class=\"source-bold\">エジプト</strong>（英）</td></tr><tr><td>イェルサレム</td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"green\" data-source-marker=\"area\" style=\"color:#859476\">●</span></td><td>オスマン帝国の最大領域</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"area\" style=\"color:#ef6058\">●</span></td><td>第一次世界大戦直前のオスマン帝国領</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">国名</strong></span></td><td>独立国</td></tr></tbody></table></div>\n<blockquote><p>オスマン帝国はこんなに小さくなっちゃった</p></blockquote>",
  "134": "<h2>134</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> 近代の西アジア</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争に感動！ ついに青年トルコ革命が起きた</strong></span></h4>\n<p>1905年、アジア各地の民族はむちゃくちゃ盛り上がった。なぜって「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日露戦争</strong></span><strong class=\"source-bold\">で日本が勝利した</strong>」からだよ。日本にとっては「ロシアに勝った〜」くらいの印象かもしれないけど、ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>の<ruby>侵略<rt>しんりゃく</rt></ruby>に苦しむ諸民族にとっては、近代以降で「<strong class=\"source-bold\">初めてアジア（日本）がヨーロッパ（ロシア）に勝った</strong>」のが日露戦争なんだよ。しかも、<strong class=\"source-bold\">オスマン帝国はロシアの南下政策に苦しんでいる</strong>。「日本と同じことをすれば、ロシアに勝てるんじゃないか？」って、一筋の希望が見えたんだね。日本と同じっていうのは「<strong class=\"source-bold\">憲法をつくって議会を開く</strong>（つまり<strong class=\"source-bold\">立憲政</strong>だ）」ってことね。この時期のアジアで、<strong class=\"source-bold\">憲法に基づいた議会がちゃんとあるのは日本だけ</strong>なんだもん。しかも、隣国<strong class=\"source-bold\">イランは日露戦争の影響で立憲革命を始めている</strong>（このあと<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➜P.138〜139</strong></span>で話すよ）。「統一と進歩委員会」のメンバーは、「自分たちも黙っているわけにはいかない！」って思ったんだよ。そして、<strong class=\"source-bold\">立憲政復活を目指す運動</strong>が陸軍士官学校を卒業した<strong class=\"source-bold\">軍のエリート（青年将校）のなかにも広がり</strong>、パリにいたメンバーの一部とオスマン帝国内の青年将校が<strong class=\"source-bold\">ギリシアのサロニカ</strong>で合流すると、エリートの<strong class=\"source-bold\">青年将校が革命の主導権を握る</strong>ことになった。</p>\n<blockquote><p>日露戦争の影響は日本人が思っているよりずっと大きい！「ヨーロッパに勝てるかも」って希望を与えたんだもん</p></blockquote>\n<p>1908年、軍人への給与の支払いが遅れたことや、ロシアとイギリスの侵略の<ruby>噂<rt>うわさ</rt></ruby>などをきっかけに軍の内部で反乱が組織され、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年トルコ革命</strong></span>が起きたよ。<strong class=\"source-bold\">アブデュルハミト2世は</strong>自分の地位を守るために<strong class=\"source-bold\">立憲政の復活を宣言</strong>（<strong class=\"source-bold\">第二次立憲政</strong>）、<strong class=\"source-bold\">「青年トルコ人」たちが政権を握った</strong>んだ。さらに翌年には、軍の内部で起きた反乱をきっかけに<strong class=\"source-bold\">アブデュルハミト2世が廃位</strong>され、新しいスルタン（入試レベル外だけど、メフメト5世だよ）が即位したんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">オスマン帝国は対外危機に襲われ……結局、青年トルコの<ruby>独裁<rt>どくさい</rt></ruby>となる</strong></span></h4>\n<p><strong class=\"source-bold\">青年トルコ革命によって立憲政が復活</strong>し、憲法も改正されて<strong class=\"source-bold\">責任内閣制</strong>が実現して、オスマン帝国（トルコ）では改革が進むようにも見えたんだ。でも、現実はそんなに甘くなかったんだよ……。</p>\n<p>青年トルコ革命は、<strong class=\"source-bold\">オスマン帝国にしてみればスルタンの専制政治を倒す近代化</strong>だけど、<strong class=\"source-bold\">周りの国から見ればただの混乱</strong>だよ。それを見た<strong class=\"source-bold\">オーストリア</strong>は「今がチャンス！」とばかりに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span>を<ruby>併合<rt>へいごう</rt></ruby>した。さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>も独立して、オスマン帝国はますます弱くなっちゃったんだ。そして、1911年にはイタリアがトリポリに攻め込んできて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア＝トルコ戦争</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！ オスマン帝国は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリポリ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キレナイカ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リビア</strong></span>）を失ってしまう。そのうえ、<strong class=\"source-bold\">ロシアの支援</strong>を受けた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルカン同盟</strong></span>（<strong class=\"source-bold\">セルビア・モンテネグロ・ブルガリア・ギリシア</strong>）が<ruby>宣戦<rt>せんせん</rt></ruby>し</p>",
  "135": "<h2>135</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ガージャール朝の衰退と混乱</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>てきて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次バルカン戦争</strong></span>が起こり、オスマン帝国は敗れてしまった。まとめて書くと、この時期のオスマン帝国の負け方はハンパないな。</p>\n<p>こうなると、国内の改革よりも「<strong class=\"source-bold\">対外危機からどうやってオスマン帝国を守るか？</strong>」ということのほうが重要になってきたんだ。「青年トルコ」政権は、この危機を乗り切るために「<strong class=\"source-bold\">トルコ民族主義【パン＝トルコ主義】</strong>」に傾いていったんだよ。トルコ民族主義っていうのは、セルジューク朝以来のイスラーム世界におけるトルコ人の<ruby>覇権<rt>はけん</rt></ruby>を背景に、「<strong class=\"source-bold\">全世界のトルコ人をオスマン帝国のもとに結集</strong>して、ヨーロッパの支配に対抗する」っていう考え方だよ。だって、<strong class=\"source-bold\">中央アジアやインドにもトルコ系のイスラーム教徒がいっぱいいる</strong>もんね。この思想を背景にして、オスマン帝国は<strong class=\"source-bold\">青年トルコの独裁体制</strong>に変わってしまったんだよ。そして……対外危機を背景に<strong class=\"source-bold\">ドイツに接近してしまった</strong>ことで、<strong class=\"source-bold\">第一次世界大戦では敗戦国</strong>となって<ruby>亡国<rt>ぼうこく</rt></ruby>の危機を迎えることになるんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ガージャール朝の衰退と混乱</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">近代のイラン（ガージャール朝）</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> ロシアの侵略</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコマンチャーイ条約</strong></span> [1828]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><strong class=\"source-bold\">ロシアにアルメニア</strong>の大半を<ruby>割譲<rt>かつじょう</rt></ruby>。<strong class=\"source-bold\">治外法権を承認</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バーブ教徒の乱</strong></span> [1848]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バーブ教</strong></span>……<strong class=\"source-bold\">サイイド＝アリー＝ムハンマド</strong>が創始</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span>民衆へ拡大……列強の進出、およびガージャール朝に対する不満が背景</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">教祖は公開処刑</strong>されたが、全国的な反乱に拡大</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> イギリス vs. ロシアの対立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">イギリス</strong>……<strong class=\"source-bold\">アフガニスタン</strong>に進出</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">ロシア</strong>……<strong class=\"source-bold\">ウズベク3ハン国</strong>への進出</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><strong class=\"source-bold\">ブハラ＝ハン国</strong>、<strong class=\"source-bold\">ヒヴァ＝ハン国</strong>保護国化。<strong class=\"source-bold\">コーカンド＝ハン国</strong>併合</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タバコ＝ボイコット運動</strong></span> [1891〜92]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>ガージャール朝が<strong class=\"source-bold\">イギリス業者にタバコの独占生産・販売権</strong>を与える</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">ウラマーの指導で</strong>、全国的なボイコット運動に発展</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン立憲革命</strong></span> [1905〜11] ……<strong class=\"source-bold\">日露戦争における日本の勝利</strong>が影響</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><strong class=\"source-bold\">ウラマー</strong>を中心とする立憲運動 <span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">憲法制定、国民議会の創設</strong></p>\n<p>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英露協商</strong></span> [1907]……イギリスとロシアが、<strong class=\"source-bold\">イランにおける勢力圏を画定</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">ロシアの軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong>により<strong class=\"source-bold\">議会が閉鎖</strong>された [1911]</p></blockquote>",
  "136": "<h2>136</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> 近代の西アジア</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ガージャール朝の衰退。イランにもヨーロッパが<ruby>侵略<rt>しんりゃく</rt></ruby>してきた！</strong></span></h4>\n<p>それじゃトルコの話はひと区切りして、イランに進もう。<strong class=\"source-bold\">サファヴィー朝が崩壊</strong>してからイランはずっと混乱していたんだけど、18世紀末に<strong class=\"source-bold\">アーガー＝ムハンマド</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガージャール朝</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カージャール朝</strong></span>】を建てて、イランを統合したよ。ガージャール朝の支配した地域はイランだけど、<strong class=\"source-bold\">国王（シャー）はトルコ人</strong>だ。つまり、<strong class=\"source-bold\">イラン人がトルコ人に支配されている</strong>という状態だよ。これ、あとで出てくるから頭に入れておいてね。</p>\n<h3><strong class=\"source-bold\">〈近代のイラン〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><strong class=\"source-bold\">ロシア帝国</strong></td></tr><tr><td>イリ事件 <br>→イリ条約[1881]</td></tr><tr><td><strong class=\"source-bold\">清</strong></td></tr><tr><td><strong class=\"source-bold\">グルジア</strong> <br><strong class=\"source-bold\">(現ジョージア)</strong></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\">黒海</em></td></tr><tr><td><strong class=\"source-bold\">アルメニア</strong></td></tr><tr><td><strong class=\"source-bold\">アゼルバイジャン</strong></td></tr><tr><td><em data-source-italic=\"true\" style=\"font-style:italic\">カスピ海</em></td></tr><tr><td><strong class=\"source-bold\">ヒヴァ＝ハン国</strong></td></tr><tr><td><strong class=\"source-bold\">コーカンド＝ハン国</strong></td></tr><tr><td><strong class=\"source-bold\">ブハラ＝ハン国</strong></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国</strong> <br><strong class=\"source-bold\">(トルコ)</strong></td></tr><tr><td>テヘラン</td></tr><tr><td><strong class=\"source-bold\">アフガニスタン</strong></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">英露協商による <br>勢力圏画定</span></td></tr><tr><td><strong class=\"source-bold\">ガージャール朝ペルシア</strong></td></tr><tr><td><strong class=\"source-bold\">英領インド</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"green\" data-source-marker=\"hatch\" style=\"color:#315837\">////</span></td><td>露の勢力圏</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"hatch\" style=\"color:#ef6058\">≡</span></td><td>英の勢力圏</td></tr></tbody></table></div>\n<blockquote><p>イギリスとロシアの対立がイランを苦しめるんだ</p></blockquote>\n<p>19世紀に入ると、トルコと同じように<strong class=\"source-bold\">イランもヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>の侵略を受け始めた</strong>。ちょうどヨーロッパではフランス革命の時期だよね。インド支配を確立したイ</p>",
  "137": "<h2>137</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ガージャール朝の衰退と混乱</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>ギリスは、<strong class=\"source-bold\">インドの防衛のためにアフガニスタンやイランへの進出</strong>を狙い、<strong class=\"source-bold\">ロシアはカフカス【コーカサス】</strong>（黒海とカスピ海の間ね）<strong class=\"source-bold\">のアルメニアやアゼルバイジャン、あるいは中央アジアへと進出</strong>してきた。こうしたヨーロッパ諸国の勢力争いが、イランにも影響を与えるんだよ。</p>\n<p>まず、<strong class=\"source-bold\">南下政策を進めるロシア</strong>が<strong class=\"source-bold\">グルジア</strong>（現ジョージア）に侵攻してきて、国境をめぐって2度の戦争になったけど、これに敗れた<strong class=\"source-bold\">ガージャール朝</strong>は、1828年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルコマンチャーイ条約</strong></span>で<strong class=\"source-bold\">アルメニアとアゼルバイジャン</strong>の北半分を<strong class=\"source-bold\">ロシアに<ruby>割譲<rt>かつじょう</rt></ruby></strong>し、さらに<strong class=\"source-bold\">治外法権や関税自主権の<ruby>喪失<rt>そうしつ</rt></ruby></strong>まで認めることになった。そして<strong class=\"source-bold\">ロシアが中央アジアへ進出</strong>し始めると、<strong class=\"source-bold\">ロシアを警戒するイギリスも進出</strong>してくるよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">英、露、ガージャール朝への不満からバーブ教徒が反乱を起こした</strong></span></h4>\n<p>こうした列強の侵略によって、19世紀のイランは領土が減ってしまうだけではなく、<strong class=\"source-bold\">イギリスなどから機械製の綿織物などが入ってきて国内の絹織物業が崩壊</strong>し、経済的にも人びとの生活が脅かされた。そして、<strong class=\"source-bold\">民衆やウラマー</strong>（イスラーム法学者だよ）<strong class=\"source-bold\">の間で、救世主（マフディー）が現れることに期待する動き</strong>が出てきたんだ。これは、キリスト教徒の<strong class=\"source-bold\">ヨーロッパ諸国に対抗</strong>する動きと考えることもできるね。同時に、イラン人のなかにはある不満があるんだよ。それは「<strong class=\"source-bold\">トルコ人（つまりガージャール朝）に支配されている</strong>」っていう不満なんだ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シーア派</strong></span>の<strong class=\"source-bold\">十二イマーム派</strong>が国教だったイランでは、シーア派の指導者の一部や<strong class=\"source-bold\">民衆がガージャール朝に反発する運動を始めていた</strong>んだよ。</p>\n<p>そして、イスラーム教シーア派から新しい宗教も生まれたんだ。それが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バーブ教</strong></span>だよ。<strong class=\"source-bold\">サイイド＝アリー＝ムハンマド</strong>が自分を「<strong class=\"source-bold\">マフディーと民衆をつなぐ門（バーブ）</strong>」と称して、これまでの宗教儀礼を廃止して、近代的な商取引や財産権、さらには男女平等など広く社会全体に広がる改革を主張した。これって<strong class=\"source-bold\">自由主義思想の影響</strong>を受けてるよね。しかも、イスラーム教から分かれるってことだ。これが<strong class=\"source-bold\">救世主を求める民衆の動きと結びついて</strong>信者が増加し、ついには<strong class=\"source-bold\">信者が各地で反乱</strong>を起こしたんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バーブ教徒の乱</strong></span>だよ。<strong class=\"source-bold\">サイイド＝アリー＝ムハンマドは反乱とは直接関係なかった</strong>んだけど、危険人物として<strong class=\"source-bold\">処刑</strong>され、反乱自体も政府によって徹底的に<ruby>弾圧<rt>だんあつ</rt></ruby>された。<ruby>鎮圧<rt>ちんあつ</rt></ruby>はされてしまったけれど、バーブ教は聖典にペルシア語を使ったり、イスラーム<ruby>暦<rt>れき</rt></ruby>ではなくイランの伝統的な太陽暦を使ったりと、<strong class=\"source-bold\">イランのナショナリズムが現れた</strong>ものとも考えられるね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">利権の切り売りへの反発から、タバコ＝ボイコット運動が起きた！</strong></span></h4>\n<p>列強の侵略に対し、<strong class=\"source-bold\">ガージャール朝</strong>も官僚制の整備による中央集権化や西洋式の軍団の編成、軍需工場の建設などの<strong class=\"source-bold\">近代化を進めた</strong>よ。でも、改革にはお金がかかるし、イギリスとロシアの対立と進出が続いている。そこで、<strong class=\"source-bold\">イギリスとロシアの勢力<ruby>均衡<rt>きんこう</rt></ruby></strong>によってイランの自立をはかるとともに、財政の不足を補うため、<strong class=\"source-bold\">列強にさまざまな利権を売却したり譲渡したりした</strong>んだよ。簡単に言うと、国を切り売り</p>",
  "138": "<h2>138</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第7回</strong></span> 近代の西アジア</p>\n<p>するの。イギリスなどの外国資本に対して鉱山・銀行・電信線を敷くなどの利権や、独占販売権などを売って、そのお金で財政を補うってわけ。てか、こんなことしたら余計に<ruby>列強<rt>れっきょう</rt></ruby>に進出されちゃうよね。</p>\n<p>そして、ガージャール朝が<strong class=\"source-bold\">イギリスの業者にタバコの独占生産・販売の利権</strong>を与えると、これを知った<strong class=\"source-bold\">イランのタバコ生産者や商人・民衆・ウラマー（イスラーム法学者）は猛反発</strong>！ さらに、<strong class=\"source-bold\">パン＝イスラーム主義</strong>を唱える<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフガーニー</strong></span>は、利権の譲渡を「イランの民族的な危機を招く！」って大反対し、イギリスの支配やシャーの専制政治へと抵抗を呼びかけた。そして、十二イマーム派の最高指導者が「タバコを吸うことは<ruby>不浄<rt>ふじょう</rt></ruby>であり、イスラームの教えに反する」と発表すると、イラン全土で一斉に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タバコ＝ボイコット運動</strong></span>が始まったんだ。この運動は単なる禁煙っていう意味じゃなくて、<strong class=\"source-bold\">反イギリス、反ガージャール朝</strong>の動きのシンボルが「タバコのボイコット」っていう形になったんだよ。最終的には首都テヘランでの大規模なデモにまで発展してしまい、<strong class=\"source-bold\">シャーはタバコ利権の<ruby>破棄<rt>はき</rt></ruby>を発表</strong>するしかなくなったんだ。</p>\n<blockquote><p>お酒を禁止されてるイスラーム教徒にとって、タバコは一番の嗜好品！ これをみんなでボイコットするなんて大事件だ！</p></blockquote>\n<p>この運動によって、<strong class=\"source-bold\">イラン人の民族意識が高まり、ウラマーがその中心となった</strong>。だからこれ以降、改革運動に対するウラマーの影響力はとても強くなるよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">中央アジアをめぐって、イギリスとロシアが激しく対立！</strong></span></h4>\n<p>19世紀後半になるとロシアは中央アジアに侵攻して、トルコ系ウズベク人の<strong class=\"source-bold\">ブハラ＝ハン国、ヒヴァ＝ハン国</strong>を保護国に、さらに<strong class=\"source-bold\">コーカンド＝ハン国</strong>も<ruby>併合<rt>へいごう</rt></ruby>した（ロシア領トルキスタン）。これに反発したコーカンド＝ハン国の将軍<strong class=\"source-bold\">ヤークーブ＝ベク</strong>は、<ruby>清<rt>シン</rt></ruby>朝が支配する<ruby>新疆<rt>しんきょう</rt></ruby>に攻め込んで独立国をつくろうとしたんだけど、ロシアは、ドサクサに紛れて<strong class=\"source-bold\">新疆のイリ地方を占領</strong>した。でも清朝も黙って見てたわけじゃないよ。<ruby>左宗棠<rt>さそうとう</rt></ruby>（洋務運動の推進者の一人）を中心に軍を送ってヤークーブ＝ベクを破り、ロシアとも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イリ条約</strong></span>を結んで<strong class=\"source-bold\">イリ地方を取り戻した</strong><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➜P.167</strong></span>。</p>\n<p>インド防衛を最優先するイギリスは、ロシアの中央アジアでの南下を警戒し、インド側からアフガニスタンに<ruby>侵攻<rt>しんこう</rt></ruby>！ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフガン戦争</strong></span>が起きた。そして、<strong class=\"source-bold\">第2次アフガン戦争のあと</strong>、イギリスは<strong class=\"source-bold\">アフガニスタンを保護国にした</strong>んだ。ここでもイギリス vs. ロシアの対立は激しかったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争の影響を受けて、イラン立憲革命が起きた！</strong></span></h4>\n<p>タバコ＝ボイコット運動以降、イランでは<strong class=\"source-bold\">ガージャール朝の専制政治に対する批判</strong>が高まっていたんだけど、それが一気に高まるのが1905年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日露戦争</strong></span>の<strong class=\"source-bold\">影響</strong>だ</p>",
  "139": "<h2>139</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ガージャール朝の衰退と混乱</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>よ。さっきオスマン帝国のとこでも出てきたけど、日本と同じように「<strong class=\"source-bold\">憲法をつくって議会を開く</strong>」、つまり<strong class=\"source-bold\">立憲政</strong>にしなきゃダメだ、って思ったんだ。こうして、<strong class=\"source-bold\">ウラマーを中心に</strong>テヘランの商人たちが<strong class=\"source-bold\">立憲政の樹立を求める</strong>ストライキを始めると、全国各地に広がり、さらにはテヘランではイギリス公使館に1万人以上が立てこもった。この動きを抑えきれなくなったシャーは、<strong class=\"source-bold\">憲法の制定と議会の開設を約束</strong>して、ようやく革命運動を抑えたんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン立憲革命</strong></span>だよ。</p>\n<p>こうして1906年には<strong class=\"source-bold\">議会が開設され、憲法も発布された</strong>んだ。やっとイランにも近代的な立憲政が成立して、「改革が進むかな〜」って思ってたのに……。<strong class=\"source-bold\">これを<ruby>潰<rt>つぶ</rt></ruby>したのはイギリスとロシア</strong>なんだよ。1907年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>英露<rt>えいろ</rt></ruby>協商</strong></span>が成立すると、<strong class=\"source-bold\">イギリスとロシアはイランの分割を決めて</strong>しまい、しかもロシアが「イランの立憲革命を潰したい」と言うと、イギリスは「気づかなかったことにするから、勝手にやっていい」って言ったんだ。こうして<strong class=\"source-bold\">イギリスの黙認</strong>のもとで<strong class=\"source-bold\">ロシアが<ruby>介入<rt>かいにゅう</rt></ruby></strong>し始め、ホントは立憲政をやりたくないシャーがこれを利用したクーデタで<strong class=\"source-bold\">議会を解散</strong>してしまったんだ。その後も、国王派と立憲派の対立と武力衝突が続いたけど、最終的には1911年、<strong class=\"source-bold\">ロシア軍の軍事介入によって議会が閉鎖されてしまった</strong>んだよ。</p>\n<blockquote><p>これも日露戦争の影響だ！ 日露戦争の衝撃の大きさがわかってきたかな？</p></blockquote>\n<p>さあ、これで近代の西アジアはおしまい。最後に年号checkだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">!!</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">年号のツボ</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">タンジマート開始</strong> [1<span data-source-color=\"red\" style=\"color:#e52715\">839</span>] （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>バ<rt>8</rt></ruby></strong></span>ラ<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>咲<rt>3</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span>庭で　ギュルハネ<ruby>勅令<rt>ちょくれい</rt></ruby>）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">ミドハト憲法</strong> [<span data-source-color=\"red\" style=\"color:#e52715\">1876</span>] （ミドハト憲法　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>嫌<rt>18</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span>ら<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無<rt>6</rt></ruby></strong></span>視）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">青年トルコ革命</strong> [<span data-source-color=\"red\" style=\"color:#e52715\">1908</span>] （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひど<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>は<rt>0</rt></ruby><ruby>や<rt>8</rt></ruby></strong></span>るな　青年トルコ）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">バーブ教徒の乱</strong> [<span data-source-color=\"red\" style=\"color:#e52715\">1848</span>] （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>晩<rt>8</rt></ruby><ruby style=\"ruby-position:under\"><ruby style=\"ruby-position:over\">縛<rt>48</rt></ruby><rt>シバ</rt></ruby></strong></span>って　教祖を処刑）</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span>二月革命、『共産党宣言』、カリフォルニアのゴールドラッシュと同じ年だ</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">タバコ＝ボイコット運動</strong> [1<span data-source-color=\"red\" style=\"color:#e52715\">891</span>] （今日から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>吐<rt>8</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>息<rt>1</rt></ruby></strong></span>　煙くない）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">イラン立憲革命</strong> [<span data-source-color=\"red\" style=\"color:#e52715\">1905</span>] （ロシアの介入　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひど<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span><ruby style=\"ruby-position:under\"><ruby style=\"ruby-position:over\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷</strong></span><rt><span data-source-color=\"red\" style=\"color:#e52715\">0</span></rt></ruby><ruby style=\"ruby-position:over\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">酷</strong></span><rt><span data-source-color=\"red\" style=\"color:#e52715\">5</span></rt></ruby><rt><span data-source-color=\"red\" style=\"color:#e52715\">レイコ</span>ク</rt></ruby>）</p></blockquote>\n<p>次回は<strong class=\"source-bold\">インドと東南アジア</strong>だよ。ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>による植民地化、そして日露戦争の影響もポイントだ！ ヨーロッパ史ともしっかりつなげてね〜。</p>"
};

